head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 editFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0:text) / col2(인덱스1:text, 숫자값)
//  - 2줄 = col3(인덱스2:text) / col4(인덱스3:text, 숫자값)
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
//  - setColumnEditFormat 은 inputType="text" 인 Column 에서 동작
//    -> 시각적으로 같은 위치(우측)에 놓인 col2(인덱스1) / col4(인덱스3) 도 고유 인덱스로 구분되어
//       지정한 인덱스의 Column 에만 editFormat 이 적용됨
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0:text)/col2(1:text, 숫자), 2줄 col3(2:text)/col4(3:text, 숫자) 고유 인덱스. col2(1) 와 col4(3) 은 화면상 같은 우측 위치이나 고유 인덱스가 다름. 데이터 Row 3개.\n[절차] columnInfo(0~3) 선택 -> (setColumnEditFormat 실행, 마스크 ####-##-## 고정). 해당 Column 셀 더블클릭 편집 후 포커스아웃하면 편집값/표시값이 자동 출력됨.\n[확인] MultiLine 이어도 col1~col4 는 고유 인덱스(0~3)로 각각 지목됨. 인덱스 1(col2) 적용 시 우측 위치가 같은 인덱스 3(col4) 은 영향 없이 원래 표시값 유지(반대도 동일). getColumnEditFormat(인덱스)/getColumnID(인덱스) 매핑도 출력."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  - col1:text(지점명) / col2:숫자(개설일자리) / col3:text(상태) / col4:숫자(점검일자리)
    let strData = '';
    strData += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strData += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strData += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strData += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "20250115", "col3": "정상영업", "col4": "20250701" },
        { "col1": "부산 해운대점", "col2": "20250220", "col3": "정상영업", "col4": "20250815" },
        { "col1": "대구 수성점", "col2": "20250312", "col3": "리모델링", "col4": "20250920" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0:text) / col2(1:text)
    //  - 2줄 : col3(2:text) / col4(3:text)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    //  - 모든 Body Column inputType="text" -> setColumnEditFormat 동작 조건 충족
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;" editable="true" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="개설일자리(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="운영상태(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="점검일자리(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : col1 (text, 1줄 첫 컬럼, 고유 인덱스 0)
    strTarget += '<w2:column width="280" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : col2 (text, 1줄 우측, 고유 인덱스 1)
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : col3 (text, 2줄 첫 컬럼, 고유 인덱스 2)
    strTarget += '<w2:column width="280" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    // index 3 : col4 (text, 2줄 우측, 고유 인덱스 3. col2 와 시각적 위치 동일하나 인덱스 다름)
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [실행] setColumnEditFormat : 선택한 컬럼(고유 누적 인덱스) 에만 editFormat 속성을 설정
//  - MultiLine(2줄) 이어도 col1~col4 는 고유 인덱스(0~3) 로 정확히 지목됨
//  - 시각적으로 같은 우측 위치인 col2(인덱스1) / col4(인덱스3) 도 고유 인덱스로 구분됨
//  - 적용 후 getColumnEditFormat 으로 설정값 확인, 각 컬럼 표시값으로 영향 범위 확인
scwin.btn_setColumnEditFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)

    // 고유 인덱스로 해당 컬럼에만 editFormat 설정
    target1.setColumnEditFormat(columnInfo, "####-##-##");

    // set 확인 : 쌍이 되는 get 메소드로 설정값 확인
    let ef = target1.getColumnEditFormat(columnInfo);

    // 4개 컬럼 표시값 -> 지정 인덱스 컬럼만 변경, 같은 우측 위치의 다른 인덱스 컬럼은 영향 없음 확인
    let msg = "setColumnEditFormat(" + columnInfo + ", '####-##-##') [인덱스 " + columnInfo + " -> getColumnID:" + colID + "]";
    msg += "\n[설정확인 getColumnEditFormat] " + ef;
    msg += "\n[인덱스0 col1] " + scwin.collectColText(0).join(', ');
    msg += "\n[인덱스1 col2] " + scwin.collectColText(1).join(', ');
    msg += "\n[인덱스2 col3] " + scwin.collectColText(2).join(', ');
    msg += "\n[인덱스3 col4] " + scwin.collectColText(3).join(', ');
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// 해당 Column 의 모든 Row 화면 표시값(td.textContent) 수집
scwin.collectColText = function (colIndex) {
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + colIndex + "']");
        arr.push(td ? td.textContent.trim() : '');
    }
    return arr;
}

// [이벤트] 셀을 직접 편집 -> 포커스 아웃(onafteredit) 하는 실제 인터랙션마다 편집값/표시값 자동 출력
//  - editFormat 적용된 Column 은 마스크에 맞지 않는 문자가 입력되지 않으며, 확정 시 마스크 형식으로 표시됨
scwin.target1_onbeforeedit = function (row, col, value) {
    scwin._editValue = value;
};
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    // onafteredit 의 value 는 마스크 미적용 원본값이므로, 편집 입력창(G_...target1__<colID>) 의 마스크 적용값을 캡처
    let editor = document.querySelector("input[id^='G_'][id$='target1__" + colID + "']");
    let editVal = editor ? editor.value : value;
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");
    let dispVal = td ? td.textContent.trim() : '';
    let msg = "편집->포커스아웃 [" + colID + "] (" + row + "," + col + ") 고유 인덱스 " + col;
    msg += "\n[편집값] " + editVal;
    msg += "\n[표시값] " + dispVal;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};
